export const getListOmieClientesUrl = (base: 'education' | 'store',
    params?: ListOmieClientesParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/admin/omie/${base}/clientes?${stringifiedParams}` : `/api/admin/omie/${base}/clientes`
}

